// ======= PREENCHA AQUI (só uma vez) =======
return [{
  json: {
    SUPABASE_URL: 'https://SEU-PROJETO.supabase.co',
    SUPABASE_SERVICE_KEY: 'COLE_A_CHAVE_SERVICE_ROLE',   // Supabase > Project Settings > API > service_role
    TOKEN_META: 'COLE_O_TOKEN_DA_PAGINA',                 // token de longa duração da Página (veja o guia)
    IG_USER_ID: 'COLE_O_ID_DO_INSTAGRAM',                 // id da conta profissional (instagram_business_account)
    PAGE_ID: 'COLE_O_ID_DA_PAGINA',                       // id da Página do Facebook ligada ao Instagram
    MEU_USUARIO: 'ia.antoniomongelli',
    GRAPH: 'https://graph.facebook.com/v23.0',
  },
}];

// Publica no Instagram todos os posts da fila cuja hora chegou.
const cfg = $('Configuração').first().json;
const helpers = this.helpers;
const esperar = (ms) => new Promise((r) => setTimeout(r, ms));

async function supa(fn, body = {}) {
  return helpers.httpRequest({
    method: 'POST',
    url: `${cfg.SUPABASE_URL}/rest/v1/rpc/${fn}`,
    headers: { apikey: cfg.SUPABASE_SERVICE_KEY, Authorization: `Bearer ${cfg.SUPABASE_SERVICE_KEY}`, 'Content-Type': 'application/json' },
    body, json: true,
  });
}

async function graph(method, caminho, dados = {}) {
  const r = await helpers.httpRequest({
    method,
    url: `${cfg.GRAPH}/${caminho}`,
    qs: { access_token: cfg.TOKEN_META, ...(method === 'GET' ? dados : {}) },
    body: method === 'GET' ? undefined : dados,
    json: true,
    ignoreHttpStatusErrors: true,
  });
  if (!r || r.error) throw new Error(r?.error?.error_user_msg || r?.error?.message || 'Erro desconhecido na API da Meta');
  return r;
}

// espera o Instagram terminar de processar a mídia (reel pode levar alguns minutos)
async function esperarPronto(containerId) {
  for (let i = 0; i < 40; i++) {
    const s = await graph('GET', containerId, { fields: 'status_code,status' });
    if (s.status_code === 'FINISHED') return;
    if (s.status_code === 'ERROR' || s.status_code === 'EXPIRED') throw new Error(`Mídia recusada: ${s.status || s.status_code}`);
    await esperar(i < 6 ? 5000 : 15000);
  }
  throw new Error('O Instagram demorou demais para processar a mídia');
}

const posts = (await supa('instagram_pegar_posts_devidos')) || [];
const resultado = [];

for (const p of posts) {
  try {
    let containerId;
    if (p.tipo === 'imagem') {
      containerId = (await graph('POST', `${cfg.IG_USER_ID}/media`, { image_url: p.midias[0], caption: p.legenda })).id;
    } else if (p.tipo === 'reel') {
      const dados = { media_type: 'REELS', video_url: p.midias[0], caption: p.legenda, share_to_feed: true };
      if (p.capa_url) dados.cover_url = p.capa_url;
      containerId = (await graph('POST', `${cfg.IG_USER_ID}/media`, dados)).id;
    } else {
      const filhos = [];
      for (const url of p.midias) {
        const f = await graph('POST', `${cfg.IG_USER_ID}/media`, { image_url: url, is_carousel_item: true });
        await esperarPronto(f.id);
        filhos.push(f.id);
      }
      containerId = (await graph('POST', `${cfg.IG_USER_ID}/media`, { media_type: 'CAROUSEL', children: filhos.join(','), caption: p.legenda })).id;
    }
    await esperarPronto(containerId);
    const pub = await graph('POST', `${cfg.IG_USER_ID}/media_publish`, { creation_id: containerId });
    let link = null;
    try { link = (await graph('GET', pub.id, { fields: 'permalink' })).permalink; } catch (e) {}
    await supa('instagram_marcar_post', { p_id: p.id, p_ok: true, p_media_id: pub.id, p_permalink: link, p_erro: null });
    resultado.push({ json: { id: p.id, tipo: p.tipo, publicado: true, link } });
  } catch (e) {
    await supa('instagram_marcar_post', { p_id: p.id, p_ok: false, p_media_id: null, p_permalink: null, p_erro: String(e.message).slice(0, 500) });
    resultado.push({ json: { id: p.id, tipo: p.tipo, publicado: false, erro: e.message } });
  }
}

return resultado.length ? resultado : [{ json: { mensagem: 'Nenhum post na hora agora.' } }];
